def prospective(bound_descriptor):
    """Check the actual selected source bytes at the original fresh gate."""
    root = Path(__file__).parents[3]
    actual = {name: hashlib.sha256((root / name).read_bytes()).hexdigest()
              for name in _FILES}
    if actual != _FILES:
        raise ContractError('concentration_window_prospective_dependency_mismatch')
    return {'version': VERSION, 'files': actual,
            'logical_sources': deepcopy(_LOGICAL_SOURCES),
            'bound_descriptor': deepcopy(bound_descriptor)}


def retained(receipt, bound_descriptor):
    """Validate the complete known saved release, without reading current files."""
    expected = {'version': VERSION, 'files': _FILES,
                'logical_sources': _LOGICAL_SOURCES,
                'bound_descriptor': bound_descriptor}
    if receipt != expected:
        raise ContractError('concentration_window_saved_binding_mismatch')


